import { Decoration } from '@codemirror/view';
import clsx from 'clsx';

import {
  filterDecorationMark,
  filterError,
  filterFieldExistsOperator,
  filterKey,
  filterPostSpotError,
  filterPreSpotError,
  filterSpotError,
  filterStatement,
  filterValue,
  incompleteFilterStatement,
} from '../FilterField.sty.js';

export const statementMark = Decoration.mark({
  inclusive: true,
  class: clsx(filterDecorationMark, filterStatement),
  tagName: 'span',
});

export const incompleteStatementMark = Decoration.mark({
  inclusive: true,
  class: clsx(filterDecorationMark, incompleteFilterStatement),
  tagName: 'span',
});

export const existsMark = Decoration.mark({
  inclusive: true,
  class: filterFieldExistsOperator,
  tagName: 'span',
});

export const keyMark = Decoration.mark({
  inclusive: true,
  class: clsx(filterDecorationMark, filterKey),
  tagName: 'span',
});

export const valueMark = Decoration.mark({
  inclusive: true,
  class: clsx(filterDecorationMark, filterValue),
  tagName: 'span',
});

export const errorMark = Decoration.mark({
  inclusive: true,
  class: clsx(filterDecorationMark, filterError),
  tagName: 'span',
});

// The error indicator for spot errors is shifted to either before or after
// the error's position. The actual error covers a slightly bigger range to have
// a bigger hover area for showing the tooltip.
export const preSpotErrorMark = Decoration.mark({
  inclusive: true,
  class: clsx(filterDecorationMark, filterSpotError, filterPreSpotError),
  tagName: 'span',
});

export const postSpotErrorMark = Decoration.mark({
  inclusive: true,
  class: clsx(filterDecorationMark, filterSpotError, filterPostSpotError),
  tagName: 'span',
});
